INSERT INTO `content` VALUES (1,NULL,1,'Recrutement','test','<figure class=\"image\"><img></figure><h2><a href=\"/uploads/files/icone-de-bus-jaune-68d650bb039d7.png\">Récrutements</a></h2><p><a href=\"/uploads/files/icone-de-bus-jaune-68d650bb039d7.png\">test</a></p><p><a href=\"/uploads/files/ouverture-68da3765ba763.pdf\">pdf</a></p><p><a href=\"/uploads/files/export-pdf-demo-68da51cbd0240.pdf\">test upload pdf</a></p><p><img></p><figure class=\"image\"><img style=\"aspect-ratio:990/350;\" src=\"http://10.0.80.1/uploads/rentree-scolaire-67ffb596d909f.jpg\" width=\"990\" height=\"350\"></figure><p>Concours 2020</p><p>Concours numéro 01/2020 pour conducteur de file d\'attente</p><p>Détail</p><figure class=\"image\"><img></figure><p>Concours 2016</p><p>Concours n°12/2016 pour les agents de renforcement du système de sécurité des transports publics</p><p>détail&nbsp;</p><p>Contrat CDD</p><p>Recrutement à titre d\'un contrat CDD CONCOURS À TITRE D\'UN CONTRAT CDD</p><p>détail</p>',NULL,'test,article,francais','2018-03-02','2022-04-11 13:51:08','2025-09-29 09:32:08',1,1,17,NULL,0),(2,NULL,1,'Données personnel','Données personnel','<div class=\"row px-2\">\r\n\r\n    <div class=\"col-md-12 col-lg-8 col-sm-12 col-12\">\r\n\r\n        <article class=\"entry entry-single\">\r\n\r\n            <h4 class=\"entry-title\"> <a href=\"blog-single.html\">Protection des données personnelles</a></h4>\r\n            <div class=\"entry-meta\">\r\n                <ul class=\"list-inline\">\r\n                    <li class=\"d-flex align-items-center\"><i class=\"bi bi-person\"></i> <a href=\"blog-single.html\">John Doe</a></li>\r\n                    <li class=\"d-flex align-items-center\"><i class=\"bi bi-clock\"></i> <a href=\"blog-single.html\"><time datetime=\"2020-01-01\">Jan 1, 2022</time></a></li>\r\n                    <li class=\"d-flex align-items-center\"><i class=\"bi bi-chat-dots\"></i> <a href=\"blog-single.html\">12 Comments</a></li>\r\n                </ul>\r\n            </div>\r\n            \r\n\r\n            <div class=\"entry-content text-justify\">\r\n                <p> Similique neque nam consequuntur ad non maxime aliquam quas. Quibusdam animi praesentium. Aliquam et laboriosam eius aut nostrum quidem aliquid dicta. Et eveniet enim. Qui velit est ea dolorem doloremque deleniti aperiam unde soluta. Est cum et quod quos aut ut et sit sunt. Voluptate porro consequatur assumenda perferendis dolore.</p>\r\n                <p> Sit repellat hic cupiditate hic ut nemo. Quis nihil sunt non reiciendis. Sequi in accusamus harum vel aspernatur. Excepturi numquam nihil cumque odio. Et voluptate cupiditate.</p>\r\n                <blockquote>\r\n                    <p> Et vero doloremque tempore voluptatem ratione vel aut. Deleniti sunt animi aut. Aut eos aliquam doloribus minus autem quos.</p>\r\n                </blockquote>\r\n                \r\n            </div>\r\n\r\n            <div class=\"entry-footer\">\r\n                <ul class=\"tags list-inline\">\r\n\r\n                    <li><a href=\"#\"><i class=\"bi bi-folder\"></i>Business</a></li>\r\n                    <li>\r\n\r\n                        <i class=\"bi bi-tags\"></i>\r\n                    </li>\r\n                    <li><a href=\"#\">Creative</a></li>\r\n                    <li><a href=\"#\">Tips</a></li>\r\n                    <li><a href=\"#\">Marketing</a></li>\r\n                </ul>\r\n            </div>\r\n\r\n        </article>\r\n    </div>\r\n\r\n    <div class=\"col-lg-4  d-none d-lg-block\">\r\n\r\n        <div class=\"card mb-0 mt-2\">\r\n            <div class=\"card-header \" style=\"    border-radius: 5px 5px 0 0;background-color:#1F487E; color:azure\">\r\n                <h5 class=\"card-title pt-1 pl-2\">Les dernières nouvelles</h5>\r\n            </div>\r\n            <div class=\"card-body\">\r\n                <!-- <h5 class=\"card-title\" style=\"text-transform: uppercase;padding-left: 20px;font-size:17px; text-align:left;font-weight:bold;color:#999\"></h5> -->\r\n                <div class=\"list-group\" style=\"padding-left:20px;padding-top:5px\">\r\n                    <a href=\"#\" class=\"list-group-item list-group-item-action flex-column align-items-start  list-group-item-adapter-first\" style=\"padding-left: 0px;\">\r\n                        <div class=\"d-flex w-100 justify-content-between\">\r\n                            <h6 class=\"mb-1 \" style=\"color:#454\">Titre de la Nouvelle</h6>\r\n\r\n                        </div>\r\n                        <small class=\"text-muted\" style=\"text-align: left;float:left\">23 Novembre 2022</small>\r\n                        <p class=\"mb-1 \" style=\"color:#666;text-align: left;float:left;margin-left:0px\">Donec id elit non mi porta gravida at eget metus. </p>\r\n                        <small style=\"text-align: left;float:left\">En savoir plus...</small>\r\n                    </a>\r\n                    <a href=\"#\" class=\"list-group-item list-group-item-action flex-column align-items-start list-group-item-adapter\" style=\"padding-left: 0px;float:left\">\r\n                        <div class=\"d-flex w-100 justify-content-between\">\r\n                            <h6 class=\"mb-1\" style=\"color:#454\">List group item heading</h6>\r\n                        </div>\r\n                        <small class=\"text-muted\" style=\"text-align: left;float:left\">23 Novembre 2022</small>\r\n                        <p class=\"mb-1\" style=\"color:#666;text-align: left;float:left;margin-left:0px\">Donec id elit non mi porta gravida at eget metus.</p>\r\n                        <small style=\"text-align: left;float:left\">En savoir plus...</small>\r\n                    </a>\r\n                    <a href=\"#\" class=\"list-group-item list-group-item-action flex-column align-items-start list-group-item-adapter\" style=\"padding-left: 0px;\">\r\n                        <div class=\"d-flex w-100 justify-content-between\">\r\n                            <h6 class=\"mb-1\" style=\"color:#454\">List group item heading</h6>\r\n                        </div>\r\n                        <small class=\"text-muted\" style=\"text-align: left;float:left\">10 Septembre 2022</small>\r\n                        <p class=\"mb-1\" style=\"color:#666;text-align: left;float:left;margin-left:0px\">Donec id elit non mi porta gravida at eget metus. M</p>\r\n                        <small style=\"text-align: left;float:left\">En savoir plus....</small>\r\n                    </a>\r\n                </div>\r\n\r\n\r\n            </div>\r\n            <a href=\"#\" class=\"card-button bg-light\" > Toutes les Nouvelles</a>\r\n            <!-- <div class=\"card-footer\" style=\"border-top: 2px solid #004c99!important;float:right\">\r\n        <small class=\"text-muted\" style=\"float:right\"><a href=\"#\">Toutes les Nouvelles</a></small>\r\n      </div> -->\r\n        </div>\r\n    </div>\r\n\r\n\r\n</div>',NULL,'apropos ; presentation entreprise','2022-05-12','2022-05-12 15:09:18','2023-05-21 08:13:19',1,3,NULL,NULL,0),(3,NULL,2,'presentation','presenetation de la service de la TRANSTU','<p>Avec le syst&egrave;me des&nbsp;<strong>Voteurs</strong>&nbsp;et la fonction&nbsp;<strong>isGranted()</strong>, vous pouvez donc contr&ocirc;ler l&#39;acc&egrave;s aux diff&eacute;rentes actions de votre site, quelle que soit la complexit&eacute; de vos r&egrave;gles m&eacute;tiers.</p>\r\n\r\n<p>Et en bonus, en environnement de d&eacute;veloppement, le profiler de s&eacute;curit&eacute; est capable de vous dire quel ou quels Voteurs ont particip&eacute; au vote. C&#39;est utile si vous ne comprenez pas pourquoi un utilisateur n&#39;a pas acc&egrave;s &agrave; une action, par exemple.presentation&nbsp;</p>',NULL,'presentation,service','2022-05-17','2022-05-17 16:12:34','2022-05-17 16:12:34',1,3,NULL,NULL,0),(4,NULL,2,'presentation  de test','test test test test test test test test test test test test test test','<h1>Authentification avec le SecurityBundle de Symfony<a href=\"https://www.univ-orleans.fr/iut-orleans/informatique/intra/tuto/php/symfony-securitybundle-auth.html#authentification-avec-le-securitybundle-de-symfony\" title=\"Lien permanent vers ce titre\">&para;</a></h1>\r\n\r\n<p>Nous allons ici pr&eacute;senter comment faire une authentification en utilisant le&nbsp;<em>SecurityBundle de Symfony</em>&nbsp;. Il permet la connexion et la navigation de mani&egrave;re s&eacute;curis&eacute;e.</p>\r\n\r\n<h2>Initialisation du projet Symfony<a href=\"https://www.univ-orleans.fr/iut-orleans/informatique/intra/tuto/php/symfony-securitybundle-auth.html#initialisation-du-projet-symfony\" title=\"Lien permanent vers ce titre\">&para;</a></h2>\r\n\r\n<p>Tout d&rsquo;abord cr&eacute;ation d&rsquo;un nouveau projet Symfony (code pour la v5 de Symfony)</p>\r\n\r\n<pre>\r\nsymfony new --full my_project\r\ncd my_project\r\n</pre>\r\n\r\n<h2>Installation de SecurityBundle<a href=\"https://www.univ-orleans.fr/iut-orleans/informatique/intra/tuto/php/symfony-securitybundle-auth.html#installation-de-securitybundle\" title=\"Lien permanent vers ce titre\">&para;</a></h2>\r\n\r\n<pre>\r\ncomposer require symfony/security-bundle\r\n</pre>',NULL,'test, test , oui','2022-05-17','2022-05-17 16:30:16','2022-05-17 16:30:16',1,1,10,NULL,0),(5,NULL,2,'presentation  de test test','voila','<h2><a href=\"https://symfony.com/doc/5.4/translation.html#forcing-the-translator-locale\" title=\"Permalink to this headline\">Forcing the Translator Locale</a></h2>\r\n\r\n<p>When translating a message, the translator uses the specified locale or the&nbsp;fallback&nbsp;locale if necessary. You can also manually specify the locale to use for translation:</p>\r\n\r\n<p>&nbsp;Copy</p>\r\n\r\n<pre>\r\n1\r\n2\r\n3\r\n4\r\n5\r\n6</pre>\r\n\r\n<pre>\r\n$translator-&gt;trans(\r\n    &#39;Symfony is great&#39;,\r\n    [],\r\n    &#39;messages&#39;,\r\n    &#39;fr_FR&#39;\r\n);</pre>\r\n\r\n<h2><a href=\"https://symfony.com/doc/5.4/translation.html#extracting-translation-contents-and-updating-catalogs-automatically\" title=\"Permalink to this headline\">Extracting Translation Contents and Updating Catalogs Automatically</a></h2>\r\n\r\n<p>The most time-consuming tasks when translating an application is to extract all the template contents to be translated and to keep all the translation files in sync. Symfony includes a command called&nbsp;translation:extract&nbsp;that helps you with these tasks:</p>\r\n\r\n<pre>\r\n# shows all the messages that should be translated for the French language\r\n$ php bin/console translation:extract --dump-messages fr\r\n\r\n# updates the French translation files with the missing strings for that locale\r\n$ php bin/console translation:extract --force fr\r\n\r\n# check out the command help to see its options (prefix, output format, domain, sorting, etc.)\r\n$ php bin/console translation:extract --help</pre>',NULL,'test ,oui,c est bien','2022-05-17','2022-05-17 17:01:24','2022-05-17 17:01:24',1,1,10,NULL,0),(6,NULL,3,'منتدى الأسئلة','منتدى الأسئلة','<div class=\"row pl-5 py-3\">\r\n  <h1>Foire de Question</h1>\r\n  <hr />\r\n</div>\r\n<div id=\"accordion\" class=\"accordion\">\r\n    <div class=\"card mb-0\">\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" href=\"#collapseOne\">\r\n            <a class=\"card-title text-uppercase \">\r\n                Q: Vous avez égaré un objet ou un bien à bord ?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseOne\" class=\"card-body collapse ml-3\" data-parent=\"#accordion\">\r\n            <p>\r\n            <h4>Q: Vous avez égaré un objet ou un bien à bord ?</h4>\r\n            <b>Answer:</b>\r\n            Vous avez égaré un objet ou un bien à bord de l\'un des moyens de transport de la TRANSTU (autobus, métro, train TGM) ?<br />\r\n            Contacter le chef de la station principale correspondante :<br />\r\n            <ul class=\"list-group-item-faq \">\r\n                <li>Stations du réseau Autobus : Farhat Hached (Place Barcelone),Habib Thameur, Ali Belhouane, Tunis Marine.</li>\r\n                <li>Stations du réseau métro : Barcelone, La République, Tunis Marine.</li>\r\n                <li>Station TGM : Tunis Marine, la Marsa.</li>\r\n            </ul>\r\n            Vous serez renseignés et aidés dans la mesure du possible pour récupérer votre bien.\r\n            </p>\r\n        </div>\r\n        <div class=\"card-header collapsed\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseTwo\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Comment se règlent les infractions?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseTwo\" class=\"card-body collapse  ml-3\" data-parent=\"#accordion\">\r\n            <p>\r\n                Comment se règlent les infractions ?<br />\r\n                <b>(Référence : Décision n°369 du 15 août 2001- Chapitre 11/Article 27 )</b> <br />\r\n\r\n                Est passible d\'une amende fixée à vingt dinars (20D) en cas de paiement immédiat et à vingt cinq dinars (25 D) en cas de paiement différé , tout voyageur surpris dans l\'une des situations irrégulières suivantes :<br />\r\n            <ul class=\"list-group-item-faq\">\r\n                <li>\r\n                    Absence de titre de transport à bord des moyens de transport et/ou à l\'intérieur des stations du métro et du TGM.\r\n                </li>\r\n                <li>\r\n                    Dépassement de section.\r\n                </li>\r\n                <li>\r\n                    Utilisation irrégulière d\'un ticket à tarif réduit.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un titre de transport hors de la zone ou de la ligne déterminant la validité de ce titre.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un abonnement scolaire en dehors de sa période de validité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un titre de transport faux ou falsifié.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une vignette d\'abonnement mensuel non accompagnée de la carte spéciale d\'identité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une vignette d\'abonnement mensuel portant numéro différent de celui de la carte spéciale d^\'identité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un ticket ou d\'une carte hebdomadaire non compostés.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une carte d\'abonnement annuel impersonnel sans présentation de l\'attestation d\'utilisation de cette carte.\r\n                </li>\r\n            </ul>\r\n            En cas de récidive au cours de la même année, l\'amende est majorée de cinq dinars (5D) par infraction commise .<br />\r\n            En cas d\'utilisation d\'une carte d\'abonnement scolaire , mensuel ou annuel dont la validité a expiré , le voyageur doit payer en sus de l\'amende indiquée au paragraphe premier du présent article , un montant correspondant à l\'utilisation de l\'abonnement depuis la date d\'expiration jusqu\'à la date de constat de l\'infraction .<br /> Toute personne dont la carte d\'abonnement a été saisie chez une tierce personne , est passible de l\'amende indiquée au paragraphe premier du présent article , si elle n\'a pas avisé la TRANSTU par écrit de la perte de la dite carte et ce dans un délai d\'une semaine.\r\n            Le refus de paiement de la pénalité entraine des poursuites judiciaires.<br />\r\n            </p>\r\n        </div>\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseThree\">\r\n            <a class=\"card-title\">\r\n                Q: Qui peut bénéficier de la gratuité du transport ?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseThree\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                Qui peut bénéficier de la gratuité du transport ?<br />\r\n                <b> (Référence : Décision n°369 du 15 août 2001- Chapitre 7/Article 16 )</b><br />\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Les enfants accompagnés et âgés de moins de 3 ans.\r\n                    </li>\r\n                    <li>\r\n                        La personne titulaire de la carte d\'handicapé et l\'accompagnant d\'un titulaire de la carte d\'handicapé portant la mention \"prioritaire avec accompagnant\".\r\n                    </li>\r\n                    <li>\r\n                        Les agents de contrôle relevant du Ministère du Transport.\r\n                    </li>\r\n                    <li>\r\n                        Les militaires de tout grade en uniforme.\r\n                    </li>\r\n                    <li>\r\n                        Les officiers, sous-officiers et élèves officiers et sous-officiers de l\'armée nationale en tenue civile sur présentation de leur carte de service.\r\n                    </li>\r\n\r\n                </ul>\r\n\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseFour\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Qui peut bénéficier du tarif réduit?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseFour\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                <b>(Référence : Décision n°369 du 15 août 2001- Chapitre 8/Article 17 )</b><br />\r\n                Peuvent bénéficier du tarif réduit :<br />\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Les enfants âgés de 3 à 7 ans ;\r\n                    </li>\r\n                    <li>\r\n                        Les journalistes sur présentation de leur carte professionnelle ;\r\n                    </li>\r\n                    <li>\r\n                        Les invalides porteurs de la carte d\'invalidité prévue par la loi N°62-34 du 14 juillet 1962 et le décret-loi n° 72-3 du 11 octobre 1972 quel que soit le taux de réduction figurant sur leur carte d\'invalidité ;\r\n                    </li>\r\n\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseFive\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Où m\'adresser pour les réclamations\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseFive\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                Ou m\'adresser pour les réclamations et les suggestions concernant le fonctionnement du réseau ?<br>\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Si vous êtes à proximité d\'une station principale ou de correspondance bus-métro, vous pouvez contacter le chef de station et remplir le formulaire avant de le remettre dans la boite aux réclamations et suggestions de la même station. </li>\r\n                    <li>\r\n                        Contactez le service Ecoute Clientèle :\r\n                        <ul class=\"list-group-item-faq  \">\r\n                            <li>\r\n                                Adresse : 60, Avenue Jean Jaurès 1000, Tunis\r\n                            </li>\r\n                            <li>\r\n                                Tél : 71 348 555\r\n                            </li>\r\n\r\n                        </ul>\r\n                    </li>\r\n                    <li>\r\n                        A travers le site de la TRANSTU \"rubrique Ecoute Clientèle\" en remplissant le formulaire disponible.\r\n                    </li>\r\n                    <li>\r\n                        A travers le courrier postal.\r\n                    </li>\r\n                    <li>\r\n                        A travers les S.M.S au numéro 87287, dans la limite de 150 caractères.\r\n                    </li>\r\n\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n\r\n\r\n    </div>\r\n</div>',NULL,'عرض,الشركة,منتدى الأسئلة','2023-06-11','2022-05-24 16:26:53','2023-06-11 14:35:33',1,2,7,NULL,1),(7,NULL,2,'show presentation','show','<p>So this should render the same thing&nbsp;as before, but with a bit more styling.&nbsp;Refresh! Ok, it&#39;s better...&nbsp;but what&#39;s up with those zero, one, two, three labels?</p>\r\n\r\n<p>This&nbsp;genusScientistForm&nbsp;is actually an entire form full of several fields.&nbsp;So, it prints out a label for the entire form...&nbsp;which is zero, one, two, three, and four.&nbsp;That&#39;s not helpful!</p>\r\n\r\n<p>Instead, print each field by hand.&nbsp;Start with&nbsp;form_errors(genusScientistForm), just in case there are any validation errors&nbsp;that are attached at this form level:</p>',NULL,'test, show','2022-05-25','2022-05-25 17:03:47','2022-05-25 17:03:47',1,2,10,NULL,0),(8,NULL,1,'FAQ','FAQ','<div class=\"row pl-5 py-3\">\r\n  <h1>Foire de Question</h1>\r\n  <hr />\r\n</div>\r\n<div id=\"accordion\" class=\"accordion\">\r\n    <div class=\"card mb-0\">\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" href=\"#collapseOne\">\r\n            <a class=\"card-title text-uppercase \">\r\n                Q: Vous avez égaré un objet ou un bien à bord ?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseOne\" class=\"card-body collapse ml-3\" data-parent=\"#accordion\">\r\n            <p>\r\n            <h4>Q: Vous avez égaré un objet ou un bien à bord ?</h4>\r\n            <b>Answer:</b>\r\n            Vous avez égaré un objet ou un bien à bord de l\'un des moyens de transport de la TRANSTU (autobus, métro, train TGM) ?<br />\r\n            Contacter le chef de la station principale correspondante :<br />\r\n            <ul class=\"list-group-item-faq \">\r\n                <li>Stations du réseau Autobus : Farhat Hached (Place Barcelone),Habib Thameur, Ali Belhouane, Tunis Marine.</li>\r\n                <li>Stations du réseau métro : Barcelone, La République, Tunis Marine.</li>\r\n                <li>Station TGM : Tunis Marine, la Marsa.</li>\r\n            </ul>\r\n            Vous serez renseignés et aidés dans la mesure du possible pour récupérer votre bien.\r\n            </p>\r\n        </div>\r\n        <div class=\"card-header collapsed\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseTwo\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Comment se règlent les infractions?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseTwo\" class=\"card-body collapse  ml-3\" data-parent=\"#accordion\">\r\n            <p>\r\n                Comment se règlent les infractions ?<br />\r\n                <b>(Référence : Décision n°369 du 15 août 2001- Chapitre 11/Article 27 )</b> <br />\r\n\r\n                Est passible d\'une amende fixée à vingt dinars (20D) en cas de paiement immédiat et à vingt cinq dinars (25 D) en cas de paiement différé , tout voyageur surpris dans l\'une des situations irrégulières suivantes :<br />\r\n            <ul class=\"list-group-item-faq\">\r\n                <li>\r\n                    Absence de titre de transport à bord des moyens de transport et/ou à l\'intérieur des stations du métro et du TGM.\r\n                </li>\r\n                <li>\r\n                    Dépassement de section.\r\n                </li>\r\n                <li>\r\n                    Utilisation irrégulière d\'un ticket à tarif réduit.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un titre de transport hors de la zone ou de la ligne déterminant la validité de ce titre.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un abonnement scolaire en dehors de sa période de validité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un titre de transport faux ou falsifié.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une vignette d\'abonnement mensuel non accompagnée de la carte spéciale d\'identité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une vignette d\'abonnement mensuel portant numéro différent de celui de la carte spéciale d^\'identité.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'un ticket ou d\'une carte hebdomadaire non compostés.\r\n                </li>\r\n                <li>\r\n                    Utilisation d\'une carte d\'abonnement annuel impersonnel sans présentation de l\'attestation d\'utilisation de cette carte.\r\n                </li>\r\n            </ul>\r\n            En cas de récidive au cours de la même année, l\'amende est majorée de cinq dinars (5D) par infraction commise .<br />\r\n            En cas d\'utilisation d\'une carte d\'abonnement scolaire , mensuel ou annuel dont la validité a expiré , le voyageur doit payer en sus de l\'amende indiquée au paragraphe premier du présent article , un montant correspondant à l\'utilisation de l\'abonnement depuis la date d\'expiration jusqu\'à la date de constat de l\'infraction .<br /> Toute personne dont la carte d\'abonnement a été saisie chez une tierce personne , est passible de l\'amende indiquée au paragraphe premier du présent article , si elle n\'a pas avisé la TRANSTU par écrit de la perte de la dite carte et ce dans un délai d\'une semaine.\r\n            Le refus de paiement de la pénalité entraine des poursuites judiciaires.<br />\r\n            </p>\r\n        </div>\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseThree\">\r\n            <a class=\"card-title\">\r\n                Q: Qui peut bénéficier de la gratuité du transport ?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseThree\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                Qui peut bénéficier de la gratuité du transport ?<br />\r\n                <b> (Référence : Décision n°369 du 15 août 2001- Chapitre 7/Article 16 )</b><br />\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Les enfants accompagnés et âgés de moins de 3 ans.\r\n                    </li>\r\n                    <li>\r\n                        La personne titulaire de la carte d\'handicapé et l\'accompagnant d\'un titulaire de la carte d\'handicapé portant la mention \"prioritaire avec accompagnant\".\r\n                    </li>\r\n                    <li>\r\n                        Les agents de contrôle relevant du Ministère du Transport.\r\n                    </li>\r\n                    <li>\r\n                        Les militaires de tout grade en uniforme.\r\n                    </li>\r\n                    <li>\r\n                        Les officiers, sous-officiers et élèves officiers et sous-officiers de l\'armée nationale en tenue civile sur présentation de leur carte de service.\r\n                    </li>\r\n\r\n                </ul>\r\n\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseFour\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Qui peut bénéficier du tarif réduit?\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseFour\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                <b>(Référence : Décision n°369 du 15 août 2001- Chapitre 8/Article 17 )</b><br />\r\n                Peuvent bénéficier du tarif réduit :<br />\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Les enfants âgés de 3 à 7 ans ;\r\n                    </li>\r\n                    <li>\r\n                        Les journalistes sur présentation de leur carte professionnelle ;\r\n                    </li>\r\n                    <li>\r\n                        Les invalides porteurs de la carte d\'invalidité prévue par la loi N°62-34 du 14 juillet 1962 et le décret-loi n° 72-3 du 11 octobre 1972 quel que soit le taux de réduction figurant sur leur carte d\'invalidité ;\r\n                    </li>\r\n\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n\r\n\r\n        <div class=\"card-header collapsed title-faq\" data-toggle=\"collapse\" data-parent=\"#accordion\" href=\"#collapseFive\">\r\n            <a class=\"card-title text-uppercase\">\r\n                Q: Où m\'adresser pour les réclamations\r\n            </a>\r\n        </div>\r\n        <div id=\"collapseFive\" class=\"collapse\" data-parent=\"#accordion\">\r\n            <div class=\"card-body ml-3\">\r\n                Ou m\'adresser pour les réclamations et les suggestions concernant le fonctionnement du réseau ?<br>\r\n                <ul class=\"list-group-item-faq-num\">\r\n                    <li>\r\n                        Si vous êtes à proximité d\'une station principale ou de correspondance bus-métro, vous pouvez contacter le chef de station et remplir le formulaire avant de le remettre dans la boite aux réclamations et suggestions de la même station. </li>\r\n                    <li>\r\n                        Contactez le service Ecoute Clientèle :\r\n                        <ul class=\"list-group-item-faq  \">\r\n                            <li>\r\n                                Adresse : 60, Avenue Jean Jaurès 1000, Tunis\r\n                            </li>\r\n                            <li>\r\n                                Tél : 71 348 555\r\n                            </li>\r\n\r\n                        </ul>\r\n                    </li>\r\n                    <li>\r\n                        A travers le site de la TRANSTU \"rubrique Ecoute Clientèle\" en remplissant le formulaire disponible.\r\n                    </li>\r\n                    <li>\r\n                        A travers le courrier postal.\r\n                    </li>\r\n                    <li>\r\n                        A travers les S.M.S au numéro 87287, dans la limite de 150 caractères.\r\n                    </li>\r\n\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n\r\n\r\n    </div>\r\n</div>',NULL,'tag, introduction','2022-06-02','2022-06-02 15:02:44','2023-05-20 22:20:48',1,2,7,NULL,0),(9,NULL,1,'Communiqués de presse',NULL,'<div class=\"row pl-5 py-3\">\r\n  <h3>Toutes les Actualités</h3>\r\n  <hr />\r\n</div>\r\n<ul>\r\n\r\n  <li>\r\n    <div class=\"row pl-4 \">\r\n      <div class=\"col-md-6 mb-4\">\r\n        <div class=\"bg-image hover-overlay ripple shadow-2-strong rounded-5\" data-mdb-ripple-color=\"light\">\r\n          <img src=\"../assets/img/img-test.jpg\" class=\"img-fluid\" />\r\n          \r\n          <a href=\"#!\">\r\n            <div class=\"mask\" style=\"background-color: rgba(251, 251, 251, 0.15);\"></div>\r\n          </a>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"col-md-6 mb-4\">\r\n        <span class=\"badge-news bg-danger px-2 py-1 shadow-1-strong mb-3\">News of the day</span>\r\n        <h4><strong>29 août 2022 : Vente des abonnements scolaires et universitaires 2022/ 2023</strong></h4>\r\n        <div class=\"entry-meta\">\r\n          <ul class=\"list-inline\" style=\"list-style: none;\">\r\n            <li class=\"posted-by\"><i class=\"fa fa-user\"></i> by <a href=\"#\">Owen Williams</a></li>\r\n            <li class=\"publish-date\"><a href=\"#\"><i class=\"bi bi-calendar3\"></i> Nov 15, 2018 </a></li>\r\n            <li class=\"views\"><a href=\"#\"><i class=\"fa fa-eye\"></i>15k</a></li>\r\n          </ul>\r\n        </div>\r\n        <p class=\"text-muted\">\r\n        La campagne de vente des abonnements scolaires et universitaire (lignes bus, métro et ligne TGM) 2022/2023 démarrera le lundi 29 août 2022. \r\n        A cet effet, 143 bureaux de poste, dont 122 sont à        </p>\r\n        <button type=\"button\"  onclick=\"document.location.href=\'article.php\'\" class=\"btn btn-primary-news\">Lire la suite</button>\r\n      </div>\r\n    </div>\r\n  </li>\r\n  <li>\r\n    <div class=\"row pl-4 \">\r\n      <div class=\"col-md-6 mb-4\">\r\n        <div class=\"bg-image hover-overlay ripple shadow-2-strong rounded-5\" data-mdb-ripple-color=\"light\">\r\n          <img src=\"../assets/img/img-test.jpg\" class=\"img-fluid\" />\r\n          <a href=\"#!\">\r\n            <div class=\"mask\" style=\"background-color: rgba(251, 251, 251, 0.15);\"></div>\r\n          </a>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"col-md-6 mb-4\">\r\n        <span class=\"badge-news bg-danger px-2 py-1 shadow-1-strong mb-3\">News of the day</span>\r\n        <h4>\r\n            <strong>Reprise de la circulation sur les lignes du métro 5 et 3</strong>\r\n        </h4>\r\n        <p class=\"text-muted\">\r\n          \r\n La circulation ferroviaire a repris normalement sur les lignes de métro n°5 et n°3, \r\n après l’achèvement des travaux de renouvellement du rail entre les stations \" le campus universitaire \" et \" 14 janvier \", avant le délai imparti.\r\n        </p>\r\n        <button type=\"button\" class=\"btn btn-primary-news\"  onclick=\"document.location.href=\'article.php\'\