INSERT INTO `time_line` VALUES (1,'des travaux de réfection de la voie ferrée au niveau de Bouchoucha - Saïdia','2022-05-31','La Société des Transports de Tunis « Transtu » informe son aimable clientèle parmi les usagers de la ligne 4 du métro, qu’en raison des travaux de réfection de la voie ferrée, le trafic entre les stations « Bouchoucha » et « Saïdia » sera effectué sur une seule voie et ce à partir de samedi 26 février jusqu’à mercredi 09 mars 2022.\r\nLa Transtu tient, à ce propos, à exprimer ses excuses pour tout dérangement subi lors de ces travaux qui sont indispensables pour la sécurité du trafic.',NULL,'2022-05-31 15:49:49','2022-05-31 15:49:49',1,NULL,1,2,NULL),(2,'24 janvier 2022: Vente de la 2éme tranche des Abonnements scolaires et universitaires','2022-05-31','A cet effet, 143 bureaux de poste, dont  122 sont à l’intérieur du district du Grand Tunis, se chargeront de cette opération selon les horaires de travail des P.T.T. Et ce, en plus des cinq points de vente suivants :\r\n- Agence Commerciale  à El Mourouj 4 en face du terminus de la ligne de métro n°6,\r\n- Agence Commerciale à Cité El Khadhra à côté de la station de métro,\r\n- Agence Commerciale à la Marsa Plage.\r\n- Agence Commerciale à la station de correspondance « Slimane Kehia » à Manouba,\r\n- Agence Commerciale à la station de correspondance « khaireddine » à Manouba,\r\nIl est également possible d’acquérir ces abonnements à distance via le site web suivant:\r\nwww.ichtirak.poste.tn',NULL,'2022-05-31 16:31:30','2022-05-31 16:31:30',1,NULL,1,2,NULL),(4,'Prolongement de l’itinéraire de la ligne de bus n° 24 sans augmentation tarifaire','2022-05-31','La ligne de bus 24 reliant la station de correspondance bus/métro ” El Montazah ” et ” Sabelet Cheikh ” sera étendue de 3 km à partir du lundi 3 janvier 2022.\r\nCette ligne  arrivera   jusqu’à la région Oudhna Bourbia, à travers la ligne nationale n° 3 et ce, sans augmentation tarifaire (500 millimes).',NULL,'2022-05-31 17:06:21','2022-05-31 17:06:21',1,NULL,1,1,NULL),(5,'استعدادات شركة \"نقل تونس\" لشهر رمضان 1443هـ / 2022 م','2022-05-31','مواكبة لتنقّــلات حرفائها خلال شهر رمضان وانسجاما مع خصوصيات هذا الشهر الكريم، تولّـت شركة  \"نقل تونس\" برمجة سفرات خطوطها بصفة تتلاءم مع الأوقات الإدارية وأوقات المؤسّـسات المدرسية والجامعية. وذلك على النحو الآتي :\r\nبالنسبة لشبكة الحافلات :\r\n- الساعة 17 و30 دقيقة : موعد آخر سفرة قبل الإفطار بالنسبة للخطوط الطويلة في اتجاه الضواحي\r\n- الساعة 17 و45 دقيقة : موعد آخر سفرة قبل الإفطار بالنسبة لبقية الخطوط في اتجاه الضواحي\r\n- الساعة 19 و15 دقيقة : موعد أوّل سفرة بعد الإفطار في اتجاه الضواحي أو وسط العاصمة\r\n- الساعة 21 و30 دقيقة : موعد آخر سفرة بعد الإفطار في اتجاه الضواحي أو وسط العاصمة\r\nبالنسبة للشبكة الحديدية :\r\n1/ خطوط المترو :\r\n- الساعة 17 و55 دقيقة : موعد آخر سفرة قبل الإفطار في اتجاه الضواحي\r\n- الساعة 19 و45 دقيقة : موعد أوّل سفرة بعد الإفطار في اتجاه الضواحي أو وسط العاصمة\r\n- الساعة 22 و30 دقيقة : موعد آخر سفرة بعد الإفطار في اتجاه الضواحي\r\n- الساعة 23 و15 دقيقة : موعد آخر سفرة بعد الإفطار في اتجاه وسط العاصمة\r\n\r\n2/ الخط ت.ح.م  :\r\n- الساعة 18 : موعد آخر سفرة قبل الإفطار في اتجاه المرسى أو تونس البحرية\r\n- الساعة 19 و45 دقيقة : موعد أوّل سفرة بعد الإفطار في اتجاه المرسى أو تونس البحرية\r\n- الساعة 23 و30 دقيقة : موعد آخر سفرة بعد الإفطار في اتجاه المرسى\r\n- الساعة منتصف الليل و5 دقائق : موعد آخر سفرة بعد الإفطار في اتجاه تونس البحرية\r\n\r\nوسيتمّ تدعيم العرض خلال النصف الثاني من شهر رمضان من حيث عدد السفرات ومن حيث توقيتها وذلك مواكبة لتطوّر طلبات التنقّــل تماشيا مع الأنشطة الثقافية وأيضا الحركة التجارية التي تشهدها الاستعدادات للاحتفال بعيد الفطر.',NULL,'2022-05-31 17:08:12','2022-05-31 17:08:12',1,NULL,3,2,NULL),(6,'test','2022-06-01','test test test test test test test test test test test test test test test test test test test test test test test test test test test test test test test test test test','nat1-6297718ac7f12.jpg','2022-06-01 16:02:50','2022-06-01 16:02:50',1,NULL,1,1,NULL),(7,'test-11:30','2022-06-13','descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn descriptipn','prod-2-62a7129817eca.jpg','2022-06-13 12:34:00','2022-06-13 12:34:00',1,NULL,1,2,NULL),(8,'des travaux de réfection de la voie ferrée au niveau de Bouchoucha - Saïdia','2022-06-20','des travaux de réfection de la voie ferrée au niveau de Bouchoucha - Saïdia des travaux de réfection de la voie ferrée au niveau de Bouchoucha - Saïdia des travaux de réfection de la voie ferrée au niveau de Bouchoucha - Saïdia','tarif-abonnement-scol-2022-2023-64734e61b6b02.jpg','2022-06-20 17:14:19','2023-05-28 12:51:45',1,NULL,1,1,NULL),(9,'test-13:30','2023-05-28','description description description description description description description description description description description description description','tarif-abonnement-scol-2022-2023-647351b0573e3.jpg','2023-05-28 13:05:52','2023-05-28 13:05:52',1,NULL,1,NULL,NULL),(10,'test','2023-05-27','test','07-647351d6c107a.jpg','2023-05-28 13:06:30','2023-05-28 13:06:30',1,NULL,1,NULL,NULL);
